'use strict';

const assert = require('node:assert/strict');
const crypto = require('node:crypto');
function test(name, fn) {
    fn();
    console.log('PASS ' + name);
}

// Binding generated by upstream mavgen; neither the sender nor receiver is mocked.
const { mavlink20, MAVLink20Processor } = require(process.argv[2]);
const KEY = Uint8Array.from(Array.from({ length: 32 }, (_, index) => index));
const FIRST = 30000000;
const LINK_ID = 7;
const STREAM = '7,1,1';

function receiver() {
    const rx = new MAVLink20Processor(null, 255, 0);
    rx.signing.secret_key = KEY;
    rx.signing.timestamp = FIRST;
    return rx;
}

function signedHeartbeat(timestamp, invalid = false) {
    const tx = new MAVLink20Processor(null, 1, 1);
    tx.signing.secret_key = KEY;
    tx.signing.link_id = LINK_ID;
    tx.signing.timestamp = timestamp;
    tx.signing.sign_outgoing = true;
    const message = new mavlink20.messages.heartbeat(2, 3, 0, 0, 4, 3);
    const packet = Buffer.from(message.pack(tx));
    assert.equal(packet[2] & 1, 1, 'generated sender must emit signed MAVLink 2');
    assert.deepEqual(
        packet.subarray(-6),
        crypto.createHash('sha256').update(Buffer.from(KEY))
            .update(packet.subarray(0, -6)).digest().subarray(0, 6),
        'signature must be real and valid'
    );
    if (invalid) packet[packet.length - 1] ^= 1;
    return packet;
}

function verify(rx, timestamp, invalid = false) {
    return rx.check_signature(signedHeartbeat(timestamp, invalid), 1, 1);
}

test('invalid new-stream signature never changes trusted state', () => {
    const rx = receiver();
    assert.equal(verify(rx, FIRST + 100, true), false);
    assert.equal(Object.prototype.hasOwnProperty.call(rx.signing.stream_timestamps, STREAM), false);
    assert.equal(rx.signing.timestamp, FIRST);
    assert.equal(verify(rx, FIRST + 1), true, 'valid sender must remain admissible');
    assert.equal(rx.signing.stream_timestamps[STREAM], FIRST + 1);
});

test('newer authenticated packet advances existing stream', () => {
    const rx = receiver();
    assert.equal(verify(rx, FIRST + 1), true);
    assert.equal(verify(rx, FIRST + 2), true);
    assert.equal(rx.signing.stream_timestamps[STREAM], FIRST + 2);
});

test('duplicate and stale frames are rejected after valid advancement', () => {
    const rx = receiver();
    assert.equal(verify(rx, FIRST + 1), true);
    assert.equal(verify(rx, FIRST + 2), true);
    assert.equal(verify(rx, FIRST + 2), false);
    assert.equal(verify(rx, FIRST + 1), false);
});

test('invalid signature on existing stream preserves state', () => {
    const rx = receiver();
    assert.equal(verify(rx, FIRST + 1), true);
    assert.equal(verify(rx, FIRST + 99, true), false);
    assert.equal(rx.signing.stream_timestamps[STREAM], FIRST + 1);
    assert.equal(verify(rx, FIRST + 2), true);
    assert.equal(rx.signing.stream_timestamps[STREAM], FIRST + 2);
});

test('real decoder rejects a forged signature without poisoning a new stream', () => {
    const rx = receiver();
    assert.throws(() => rx.decode(signedHeartbeat(FIRST + 100, true)), /Invalid signature/);
    assert.equal(Object.prototype.hasOwnProperty.call(rx.signing.stream_timestamps, STREAM), false);
    assert.doesNotThrow(() => rx.decode(signedHeartbeat(FIRST + 1)));
    assert.equal(rx.signing.stream_timestamps[STREAM], FIRST + 1);
});

test('permissive callback does not promote an invalid signature into trusted state', () => {
    const rx = receiver();
    rx.signing.allow_unsigned_callback = () => true;
    assert.doesNotThrow(() => rx.decode(signedHeartbeat(FIRST + 100, true)));
    assert.equal(Object.prototype.hasOwnProperty.call(rx.signing.stream_timestamps, STREAM), false);
    assert.doesNotThrow(() => rx.decode(signedHeartbeat(FIRST + 1)));
    assert.equal(rx.signing.stream_timestamps[STREAM], FIRST + 1);
});
